export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let prevVel = { x: 0, y: 0, z: 0 };
  let prevDir = { x: 0, y: 1, z: 0 };
  let prevThrust = 0.45;
  let uFilt = 0;

  let kThrust = 21.0;
  let massEst = 0.72;
  let ayF = 9.81;
  let uyF = 9.81 / 21.0;

  let dxEst = 0, dzEst = 0;
  let dxSlow = 0, dzSlow = 0;
  let intX = 0, intY = 0, intZ = 0, intYaw = 0;

  let targetGate = -1;
  let phase = 'align';
  let settle = 0;
  let padSettle = 0;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;
      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const dir = {
        x: cy * bodyX + sy * bodyZ,
        y: Math.cos(att.pitch) * Math.cos(att.roll),
        z: -sy * bodyX + cy * bodyZ,
      };

      if (!initialized) {
        initialized = true;
        prevVel = { x: v.x, y: v.y, z: v.z };
        prevDir = dir;
      } else {
        const dtSub = 0.005, lagEst = 0.038;
        const alphaLag = 1 - Math.exp(-dtSub / lagEst);
        const u1 = uFilt + (prevThrust - uFilt) * alphaLag;
        const u2 = u1 + (prevThrust - u1) * alphaLag;
        const uAvg = 0.5 * (u1 + u2);
        uFilt = u2;

        const avgDirX = 0.5 * (prevDir.x + dir.x);
        const avgDirY = 0.5 * (prevDir.y + dir.y);
        const avgDirZ = 0.5 * (prevDir.z + dir.z);

        const vxAvg = 0.5 * (prevVel.x + v.x);
        const vyAvg = 0.5 * (prevVel.y + v.y);
        const vzAvg = 0.5 * (prevVel.z + v.z);

        const axStep = (v.x - prevVel.x) * 100;
        const ayStep = (v.y - prevVel.y) * 100;
        const azStep = (v.z - prevVel.z) * 100;

        if (p.y > 0.095 && prevThrust > 0.12 && prevThrust < 0.88 && avgDirY > 0.75) {
          const ayNeed = clamp(ayStep + 9.81 + (0.42 / massEst) * vyAvg, 2.0, 20.0);
          const uyStep = uAvg * avgDirY;
          if (uyStep > 0.15) {
            ayF += 0.10 * (ayNeed - ayF);
            uyF += 0.10 * (uyStep - uyF);
            kThrust = clamp(ayF / uyF, 17.2, 26.8);
            massEst = clamp(15.3 / kThrust, 0.60, 0.85);
          }
        }

        if (p.y > 0.085) {
          const axMod = kThrust * uAvg * avgDirX - (0.42 / massEst) * vxAvg;
          const azMod = kThrust * uAvg * avgDirZ - (0.42 / massEst) * vzAvg;
          const dxRaw = clamp(axStep - axMod, -6.0, 6.0);
          const dzRaw = clamp(azStep - azMod, -6.0, 6.0);
          dxEst += 0.24 * (dxRaw - dxEst);
          dzEst += 0.24 * (dzRaw - dzEst);
          dxSlow += 0.03 * (dxRaw - dxSlow);
          dzSlow += 0.03 * (dzRaw - dzSlow);
        }

        prevVel = { x: v.x, y: v.y, z: v.z };
        prevDir = dir;
      }

      let target = { x: p.x, y: 1.0, z: p.z };
      let ffVx = 0, ffVy = 0, ffVz = 0;
      let kpX = 6.5, kdX = 4.2, kpZ = 7.5, kdZ = 4.5, kpY = 7.5, kdY = 4.5;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetGate !== obs.gateIndex) {
          targetGate = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }

        const dxGate = gate.x - p.x;
        const dyGate = gate.y - p.y;
        const dzGate = gate.z - p.z;

        const gustJumpZ = Math.abs(dzEst - dzSlow);
        const gustJumpX = Math.abs(dxEst - dxSlow);

        if (phase === 'align') {
          const alignDist = 0.26;
          target = { x: gate.x - alignDist, y: gate.y, z: gate.z };
          kpZ = 9.0; kdZ = 5.0;
          kpY = 8.5; kdY = 4.8;
          kpX = 7.0; kdX = 4.4;

          const errAlignX = Math.abs(target.x - p.x);
          const errY = Math.abs(dyGate);
          const errZ = Math.abs(dzGate);
          const speedYZ = Math.hypot(v.y, v.z);

          if (errAlignX < 0.14 && p.x < gate.x - 0.08 && errY < 0.08 && errZ < 0.045 && speedYZ < 0.22 && Math.abs(v.x) < 0.30 && gustJumpZ < 0.9) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 6) {
            phase = 'cross';
          }
        }

        if (phase === 'cross') {
          // Predict crossing Y and Z if we continue forward
          const tCross = clamp(dxGate / Math.max(0.35, v.x), 0.02, 0.45);
          const zPred = p.z + v.z * tCross;
          const yPred = p.y + v.y * tCross;
          const zErrPred = Math.abs(gate.z - zPred);
          const yErrPred = Math.abs(gate.y - yPred);

          // If still far enough to brake and alignment is compromised by a gust, abort back to align!
          if (dxGate > 0.07 && (zErrPred > 0.075 || Math.abs(dzGate) > 0.075 || yErrPred > 0.15 || Math.abs(dyGate) > 0.15)) {
            phase = 'align';
            settle = 0;
            target = { x: gate.x - 0.26, y: gate.y, z: gate.z };
            kpX = 9.0; kdX = 5.0;
          } else {
            target = { x: gate.x + 0.32, y: gate.y, z: gate.z };
            ffVx = 0.75;
            kpZ = 10.5; kdZ = 5.4;
            kpY = 9.0; kdY = 5.0;
            kpX = 6.5; kdX = 4.0;
          }
        }
      } else {
        const pad = obs.pad.centre;
        if (targetGate !== 3) {
          targetGate = 3;
          phase = 'pad_approach';
          padSettle = 0;
        }
        const horizErr = Math.hypot(pad.x - p.x, pad.z - p.z);
        const horizSpeed = Math.hypot(v.x, v.z);

        if (phase === 'pad_approach') {
          // Smooth height transition toward pad
          const descendRef = horizErr < 0.35 ? 0.32 : 0.75;
          target = { x: pad.x, y: descendRef, z: pad.z };
          kpX = 7.0; kdX = 4.6;
          kpZ = 7.0; kdZ = 4.6;
          if (horizErr < 0.10 && horizSpeed < 0.22 && p.y < 0.42) {
            padSettle++;
          } else {
            padSettle = Math.max(0, padSettle - 1);
          }
          if (padSettle >= 6) {
            phase = 'descend';
          }
        }

        if (phase === 'descend') {
          if (horizErr > 0.135 && p.y > 0.11) {
            phase = 'pad_approach';
            padSettle = 0;
            target = { x: pad.x, y: 0.28, z: pad.z };
          } else {
            // Gentle touchdown target
            target = { x: pad.x, y: 0.055, z: pad.z };
            ffVy = p.y > 0.12 ? -0.22 : -0.05;
            kpX = 6.5; kdX = 4.5;
            kpZ = 6.5; kdZ = 4.5;
            kpY = 7.0; kdY = 5.0;
          }
        }
      }

      const ex = target.x - p.x;
      const ey = target.y - p.y;
      const ez = target.z - p.z;

      if (Math.abs(ex) < 0.35) intX = clamp(intX + ex * 0.01, -0.4, 0.4);
      else intX *= 0.98;
      if (Math.abs(ez) < 0.35) intZ = clamp(intZ + ez * 0.01, -0.4, 0.4);
      else intZ *= 0.98;
      if (p.y > 0.085) intY = clamp(intY + ey * 0.01, -0.6, 0.6);

      const axCmd = clamp(kpX * ex + kdX * (ffVx - v.x) + 0.8 * intX, -4.2, 4.2);
      const azCmd = clamp(kpZ * ez + kdZ * (ffVz - v.z) + 0.8 * intZ, -4.2, 4.2);
      const ayCmd = clamp(kpY * ey + kdY * (ffVy - v.y) + 1.8 * intY, -4.0, 5.0);

      // Desired thrust acceleration vector (compensating drag and estimated wind disturbance)
      const dragCoeff = 0.42 / massEst;
      const Tx = axCmd + dragCoeff * v.x - dxEst;
      const Tz = azCmd + dragCoeff * v.z - dzEst;
      const Ty = Math.max(4.0, 9.81 + ayCmd + dragCoeff * v.y);

      const TbodyX = cy * Tx - sy * Tz;
      const TbodyZ = sy * Tx + cy * Tz;

      let maxTilt = 0.48;
      if (obs.gateIndex === 3 && phase === 'descend' && p.y <= 0.11) {
        maxTilt = 0.14;
      }

      const pitchDes = clamp(Math.atan2(TbodyX, Ty), -maxTilt, maxTilt);
      const rollDes = clamp(Math.atan2(-TbodyZ, Math.hypot(TbodyX, Ty)), -maxTilt, maxTilt);

      // Collective thrust command
      const tiltCos = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));
      let thrust = clamp(Ty / (kThrust * tiltCos), 0.05, 0.95);

      // When settled on the pad on the floor, reduce thrust and keep level so landedFor accumulates
      if (obs.gateIndex === 3 && phase === 'descend' && p.y <= 0.092 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) <= 0.14 && Math.hypot(v.x, v.y, v.z) < 0.42) {
        thrust = clamp((9.81 - 1.5) / kThrust, 0.15, 0.38);
      }

      intYaw = clamp(intYaw + att.yaw * 0.01, -0.4, 0.4);
      const yawRate = clamp(-4.0 * att.yaw - 0.25 * rates.yaw - 2.5 * intYaw, -2.0, 2.0);

      prevThrust = thrust;
      return { thrust, roll: rollDes, pitch: pitchDes, yawRate };
    },
  };
}

