      const yawRate = clamp(-4.0 * att.yaw - 0.25 * rates.yaw - 2.5 * intYaw, -2.0, 2.0);

      prevThrust = thrust;
      return { thrust, roll: rollCmd, pitch: pitchCmd, yawRate };
    },
  };
